SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, p.hadm_id, p.stay_id, p.los, i.intime, i.outtime, i.caregiver_id, i.charttime, i.storetime, i.itemid, i.value, i.valuenum, i.valueuom, i.warning, s.status, lag(s.status) OVER (PARTITION BY p.hadm_id ORDER BY i.charttime) AS previous_status FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN services s ON i.stay_id = s.stay_id WHERE p.gender = 'M' AND p.anchor_age = 55 AND p.anchor_year BETWEEN 50 AND 60 AND s.status = 'sepsis' AND NOT EXISTS (SELECT 1 FROM procedures_icd pi WHERE pi.subject_id = p.subject_id AND pi.chartdate = i.intime - interval '1 day' AND (pi.icd_code = 'shock' OR pi.icd_code = 'shocks'));